package com.reactnativeintune

import com.facebook.react.bridge.ReactApplicationContext

/**
 * NativeIntuneSpec is generated by Codegen from src/NativeIntune.ts into
 * package.json -> codegenConfig.android.javaPackageName, which is this package — so
 * there is nothing to import.
 */
class RNIntuneModule(reactContext: ReactApplicationContext) : NativeIntuneSpec(reactContext) {

  /**
   * Placeholder from the scaffold. It exists to prove Codegen, autolinking and the
   * vendored AAR all work before any SDK code is written; it is removed with the first
   * real method (SPEC §13).
   */
  override fun multiply(a: Double, b: Double): Double {
    return a * b
  }

  companion object {
    // Resolves to "RNIntune" — the name in TurboModuleRegistry.getEnforcing (SPEC §2.2).
    const val NAME = NativeIntuneSpec.NAME
  }
}
